CREATE TABLE IF NOT EXISTS customer_pending_registrations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,phone VARCHAR(40) NULL,password_hash VARCHAR(255) NOT NULL,expires_at DATETIME NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS customer_email_otps (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(255) NOT NULL,otp_hash VARCHAR(255) NOT NULL,purpose VARCHAR(40) NOT NULL DEFAULT 'SIGNUP',expires_at DATETIME NOT NULL,attempts TINYINT UNSIGNED NOT NULL DEFAULT 0,used_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_customer_otp_lookup(email,purpose,used_at,expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
